 21	    private static void testBasicQueueOperations() {
 22	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 23	
 24	        queue.enqueue(10);
 25	        queue.enqueue(20);
 26	
 27	        assertEquals(2, queue.size(), "enqueue should increase the size");
 28	        assertEquals(1, queue.remainingCapacity(), "remaining capacity should decrease after enqueue");
 29	        assertEquals(Integer.valueOf(10), queue.peek(), "peek should return the front element");
 30	        assertEquals(Integer.valueOf(10), queue.peekFront(), "peekFront should return the front element");
 31	        assertEquals(Integer.valueOf(20), queue.peekRear(), "peekRear should return the rear element");
 32	        assertEquals(Integer.valueOf(10), queue.dequeue(), "dequeue should remove from the front");
 33	        assertEquals(Integer.valueOf(20), queue.poll(), "poll should remove and return the next element");
 34	        assertNull(queue.poll(), "poll should return null when the queue is empty");
 35	        assertThrows(IllegalStateException.class, queue::dequeue, "dequeue should throw when the queue is empty");
 36	    }
