 38	    private static void testWrapAroundBehavior() {
 39	        CircularQueue<Integer> queue = new CircularQueue<>(3);
 40	
 41	        queue.enqueue(1);
 42	        queue.enqueue(2);
 43	        queue.enqueue(3);
 44	        queue.dequeue();
 45	        queue.enqueue(4);
 46	
 47	        assertEquals("[2, 3, 4]", queue.toString(), "wrap-around should preserve iteration order");
 48	        assertEquals(Integer.valueOf(2), queue.peekFront(), "front should advance after dequeue");
 49	        assertEquals(Integer.valueOf(4), queue.peekRear(), "rear should track wrapped insertion");
 50	    }
