 74	    private static void testIteratorTraversalAndFailFastBehavior() {
 75	        CircularQueue<Integer> queue = new CircularQueue<>(4);
 76	
 77	        queue.enqueue(5);
 78	        queue.enqueue(6);
 79	        queue.enqueue(7);
